components.css:
.ds-page-index{border-top:2px solid var(--accent-blue,#234f88);padding-top:var(--space-4,1rem);font-family:var(--font-source-sans,"Source Sans 3"),sans-serif;font-size:1rem;line-height:1.7;color:var(--text-ink,#182e45);}.ds-page-index nav{display:flex;flex-wrap:wrap;gap:0 var(--space-6,1.5rem);}.ds-index-title{width:100%;margin:0 0 var(--space-2,.5rem);font-size:1rem;font-weight:600;}.ds-page-index a{display:flex;align-items:center;min-height:44px;color:var(--accent-blue,#234f88);text-decoration:underline;text-underline-offset:.22em;text-decoration-thickness:1px;}.ds-page-index a:hover{text-decoration-thickness:2px;}.ds-page-index a:focus-visible{outline:3px solid var(--focus-color,#1c5cba);outline-offset:4px;}@media(max-width:48rem){.ds-page-index{max-width:68ch;}.ds-index-title{margin-bottom:0;}}.ds-breadcrumbs{font-size: 1rem;
  color: var(--text-muted);
  margin-bottom: var(--space-8);}.ds-breadcrumbs ol{display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: var(--space-2) var(--space-4);
  list-style: none;}.ds-breadcrumbs li{display: inline-flex;
  align-items: center;
  gap: var(--space-4);
  min-height: 44px;}.ds-breadcrumbs li + li::before{content: "/";
  color: var(--text-muted);}.ds-breadcrumbs a{display: inline-flex;
  align-items: center;
  min-height: 44px;
  color: var(--accent-blue);
  text-decoration: underline;}.ds-topic-index{border-top: 2px solid var(--accent-blue);
  border-bottom: 1px solid var(--rule-color);
  padding-block: var(--space-2);
  font-size: 1rem;}.ds-topic-index summary{cursor: pointer;
  color: var(--accent-blue);
  font-weight: 600;
  padding-block: var(--space-3);
  min-height: 44px;}.ds-topic-index summary:hover{text-decoration: underline;}.ds-topic-index ol{list-style: none;}.ds-topic-index a{display: flex;
  align-items: center;
  min-height: 44px;
  padding-block: var(--space-2);
  color: var(--accent-blue);
  text-decoration: underline;}.ds-topic-index a:hover{text-decoration-thickness: 2px;}.ds-breadcrumbs,.ds-topic-index{font-family:var(--font-source-sans,"Source Sans 3"),sans-serif;line-height:1.7;}.ds-breadcrumbs ol,.ds-topic-index ol{margin:0;padding:0;}.ds-breadcrumbs a,.ds-topic-index a{text-underline-offset:.22em;text-decoration-thickness:1px;}.ds-breadcrumbs a:hover{text-decoration-thickness:2px;}.ds-breadcrumbs a:focus-visible,.ds-topic-index summary:focus-visible,.ds-topic-index a:focus-visible{outline:3px solid var(--focus-color,#1c5cba);outline-offset:4px;}.ds-lesson-index{margin-bottom:var(--space-12,3rem);}.ds-lesson-index ol{padding-block:var(--space-2,.5rem);}

.ds-subject-card{display: grid;
  grid-template-columns: 7rem minmax(0, 1.2fr) minmax(0, 1fr);
  gap: var(--space-8);
  padding: var(--space-8);
  background: var(--surface-reading);
  border: 1px solid var(--rule-color);
  color: var(--text-ink);}.ds-subject-card:hover{background: var(--accent-soft);
  border-color: var(--accent-blue);}.ds-subject-card:active{background: var(--surface-paper);}.ds-subject-card-heading h2{font-family: var(--font-source-serif), serif;
  font-size: 1.5rem;
  font-weight: 500;
  line-height: 1.35;
  text-wrap: balance;}.ds-subject-card-heading p{margin-top: var(--space-4);
  color: var(--text-muted);
  max-width: var(--reading-width);}.ds-subject-card-topics .ds-topic-label{margin-top: 0;}.ds-subject-card-topics ul{list-style: disc;
  padding-left: var(--space-4);
  font-size: 1rem;
  color: var(--text-muted);
  margin-top: var(--space-2);}.ds-subject-card-topics li + li{margin-top: var(--space-1);}.ds-subject-explore{display: inline-flex;
  align-items: center;
  gap: var(--space-4);
  color: var(--accent-blue);
  font-size: 1rem;
  font-weight: 600;
  margin-top: var(--space-6);
  min-height: 44px;
  text-decoration: underline;}.ds-subject-card:hover .ds-subject-explore, .ds-breadcrumbs a:hover{text-decoration-thickness: 2px;}.ds-subject-card{font-family:var(--font-source-sans,"Source Sans 3"),sans-serif;font-size:1.125rem;line-height:1.7;text-decoration:none;}.ds-subject-card p,.ds-subject-card h2{margin:0;}.ds-subject-card-heading p{margin-top:var(--space-4,1rem);}.ds-subject-identity{color:var(--accent-blue,#234f88);}.ds-subject-identity p{font-size:1.5rem;font-weight:600;margin-top:var(--space-4,1rem);}.ds-topic-label{color:var(--text-ink,#182e45);font-size:1rem;font-weight:600;}.ds-subject-card-topics ul{margin-bottom:0;}.ds-subject-explore{text-underline-offset:.22em;text-decoration-thickness:1px;}.ds-subject-card:focus-visible{outline:3px solid var(--focus-color,#1c5cba);outline-offset:4px;}@media(max-width:64rem){.ds-subject-card{grid-template-columns:5rem minmax(0,1fr);}.ds-subject-card-topics{grid-column:2;}}@media(max-width:48rem){.ds-subject-card{grid-template-columns:minmax(0,1fr);gap:var(--space-6,1.5rem);padding:var(--space-6,1.5rem);}.ds-subject-card .ds-subject-identity{display:flex;align-items:center;gap:var(--space-4,1rem);}.ds-subject-card .ds-subject-identity p{margin-top:0;}.ds-subject-card-heading h2{text-wrap:pretty;}.ds-subject-card-topics{grid-column:auto;}}
